import argparse,json,os
from http.server import BaseHTTPRequestHandler,HTTPServer
import store

class Handler(BaseHTTPRequestHandler):
    def reply(self,status,value):
        body=json.dumps(value,ensure_ascii=False).encode()
        self.send_response(status);self.send_header('Content-Type','application/json')
        self.send_header('Content-Length',str(len(body)));self.end_headers();self.wfile.write(body)
    def do_GET(self):
        if self.path=='/health':self.reply(200,{'ok':True})
        elif self.path=='/tasks':self.reply(200,store.read(self.server.data_path))
        else:self.reply(404,{'error':'not found'})
    def do_POST(self):
        try:body=json.loads(self.rfile.read(int(self.headers.get('Content-Length','0'))) or b'{}')
        except (ValueError,TypeError):self.reply(400,{'error':'invalid json'});return
        if self.path=='/tasks':
            if not isinstance(body.get('title'),str) or not body['title'].strip():self.reply(400,{'error':'title required'});return
            self.reply(201,store.add(self.server.data_path,body['title']));return
        if self.path.startswith('/tasks/') and self.path.endswith('/complete'):
            try:task_id=int(self.path.split('/')[2])
            except ValueError:self.reply(400,{'error':'invalid id'});return
            for task in store.read(self.server.data_path):
                if task['id']==task_id:
                    task['done']=True
                    self.reply(200,task);return
            self.reply(404,{'error':'not found'});return
        self.reply(404,{'error':'not found'})
    def log_message(self,*args):pass

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--port',type=int,default=0);parser.add_argument('--data',required=True)
    args=parser.parse_args();server=HTTPServer(('127.0.0.1',args.port),Handler);server.data_path=args.data
    print(json.dumps({'port':server.server_port,'pid':os.getpid()}),flush=True)
    try:server.serve_forever()
    finally:server.server_close()

if __name__=='__main__':main()

