import argparse,json
import store

def main():
    parser=argparse.ArgumentParser(description="任务清单")
    parser.add_argument('--data',default='tasks.json')
    commands=parser.add_subparsers(dest='command',required=True)
    add=commands.add_parser('add');add.add_argument('title')
    commands.add_parser('list')
    complete=commands.add_parser('complete');complete.add_argument('id',type=int)
    args=parser.parse_args()
    if args.command=='add': result=store.add(args.data,args.title)
    elif args.command=='complete': result=store.complete(args.data,args.id)
    else: result=store.read(args.data)
    print(json.dumps(result,ensure_ascii=False))

if __name__=='__main__':main()

fixture_source.store.py:
import json
from pathlib import Path

def read(path):
    path=Path(path)
    return json.loads(path.read_text()) if path.exists() else []

def save(path, tasks):
    Path(path).write_text(json.dumps(tasks,ensure_ascii=False))

def add(path, title):
    tasks=read(path)
    task={"id":max([x["id"] for x in tasks],default=0)+1,"title":title,"done":False}
    tasks.append(task);save(path,tasks);return task

def complete(path, task_id):
    tasks=read(path)
    for task in tasks:
        if task["id"]==task_id:
            task["done"]=True;save(path,tasks);return task
    raise KeyError(task_id)

